<script setup lang="ts">
import {ref} from 'vue'
import {NButton,NInput,NModal,NSelect} from 'naive-ui'
import {request} from '../api/client'
import {key,failure,type StockTransfer} from '../api/warehouse'
const props=defineProps<{item:StockTransfer}>(),emit=defineEmits<{changed:[];pending:[boolean]}>()
const show=ref(false),busy=ref(false),error=ref(''),line=ref(''),location=ref(''),quantity=ref(''),basis=ref(''),at=ref(new Date().toISOString()),locked=ref(false)
let pending:Record<string,unknown>|null=null
async function save(){try{if(!pending){if(!/^[0-9]+$/.test(quantity.value))throw new Error('实际数量须为非负整数');pending={line_id:line.value,location_id:location.value,observed_quantity:quantity.value,comparison_at:at.value,basis:basis.value,idempotency_key:key()};locked.value=true;emit('pending',true)}busy.value=true;await request(`/stock-transfers/${props.item.id}/differences`,'POST',pending);show.value=false;pending=null;locked.value=false;emit('pending',false);emit('changed')}catch(e){error.value=failure(e);if([400,422].includes((e as {status?:number}).status||0)){locked.value=false;pending=null;emit('pending',false);error.value=(e as Error).message+'。请修正输入后提交。'}}finally{busy.value=false}}
</script>
<template><NButton @click="show=true">记录数量差异</NButton><NModal v-model:show="show" preset="card" title="记录这条转移的数量差异" class="dialog"><p>填写该转移在所选实际地点的观察数量，不能用整仓盘点数量代替。</p><label>SKU<NSelect :disabled="locked" v-model:value="line" :options="item.lines.map(l=>({label:`${l.sku_name}（批准 ${l.quantity} ${l.unit}）`,value:l.id}))"/></label><label>实际地点<NSelect :disabled="locked" v-model:value="location" :options="[...(item.source_kind==='physical'?[{label:item.source_location_name,value:item.source_location_id}]:[]),...(item.destination_kind==='physical'?[{label:item.destination_location_name,value:item.destination_location_id}]:[])]"/></label><label>观察数量<NInput :disabled="locked" v-model:value="quantity" placeholder="非负整数"/></label><label>比较时间（含时区）<NInput :disabled="locked" v-model:value="at"/></label><label>依据<NInput :disabled="locked" v-model:value="basis"/></label><p class="error">{{error}}</p><NButton :loading="busy" @click="save">{{locked?'重试原请求':'记录差异'}}</NButton></NModal></template>
